{
  "name": "Tao-Thai (Turtle Photo Booth)",
  "description": "A parody of the famous Tao Bin vending machine, transformed into a sassy AI photo booth with 'beverage-flavored' photo filters and cheeky commentary.",
  "requestFramePermissions": [
    "camera"
  ]
}

export enum AppState {
  IDLE = 'IDLE',
  MENU = 'MENU',
  COUNTDOWN = 'COUNTDOWN',
  PROCESSING = 'PROCESSING',
  RESULT = 'RESULT'
}

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  prompt: string;
  icon: string;
  color: string;
}

export interface PhotoResult {
  imageUrl: string;
  sweetness: number;
  calories: number;
  fortune: string;
  menuName: string;
}

import { GoogleGenAI } from "@google/genai";

export const processPhoto = async (base64Image: string, prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1],
              mimeType: 'image/jpeg',
            },
          },
          {
            text: `Apply this filter logic to the image: ${prompt}. Return ONLY the edited image.`,
          },
        ],
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return base64Image; // Fallback
  } catch (error) {
    console.error("Gemini Error:", error);
    return base64Image;
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { AppState, MenuItem, PhotoResult } from './types';
import { MENU_ITEMS, INSULTS, FORTUNES } from './constants';
import { processPhoto } from './geminiService';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.IDLE);
  const [selectedMenu, setSelectedMenu] = useState<MenuItem | null>(null);
  const [countdown, setCountdown] = useState<string | number>(3);
  const [insult, setInsult] = useState("");
  const [result, setResult] = useState<PhotoResult | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      alert("Please allow camera access to use Tao-Thai!");
    }
  };

  const handleStart = () => {
    setState(AppState.MENU);
    startCamera();
  };

  const selectMenu = (menu: MenuItem) => {
    setSelectedMenu(menu);
    setState(AppState.COUNTDOWN);
    runCountdown();
  };

  const runCountdown = () => {
    let counts = [3, 2, "...", "แชะ!"];
    let i = 0;
    const interval = setInterval(() => {
      if (i < counts.length) {
        setCountdown(counts[i]);
        i++;
      } else {
        clearInterval(interval);
        takePhoto();
      }
    }, 1000);
  };

  const takePhoto = async () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg');
        setCapturedImage(dataUrl);
        setState(AppState.PROCESSING);

        // Random insult
        setInsult(INSULTS[Math.floor(Math.random() * INSULTS.length)]);

        // Call AI
        const edited = await processPhoto(dataUrl, selectedMenu?.prompt || "");

        setResult({
          imageUrl: edited,
          sweetness: Math.floor(Math.random() * 101),
          calories: Math.floor(Math.random() * 500) + 100,
          fortune: FORTUNES[Math.floor(Math.random() * FORTUNES.length)],
          menuName: selectedMenu?.name || ""
        });
        setState(AppState.RESULT);
      }
    }
  };

  const reset = () => {
    setState(AppState.IDLE);
    setResult(null);
    setCapturedImage(null);
  };

  const share = (platform: string) => {
    const messages: Record<string, string> = {
      fb: "ประกาศให้โลกยอมรับ ว่าเราสวย!",
      ig: "หลอกชาวบ้านว่าสวยด้วยเต่าถ่าย",
      tt: "เบื้องหลังความพยายามที่ล้มเหลว"
    };
    alert(`กำลังแชร์ไปที่ ${platform}: ${messages[platform]}`);
  };

  return (
    <div className="w-full max-w-md bg-white rounded-[3rem] overflow-hidden shadow-2xl vending-machine-border relative flex flex-col h-[850px]">
      {/* Header Panel */}
      <div className="bg-green-600 p-6 text-white text-center border-b-8 border-green-700">
        <h1 className="text-4xl font-extrabold tracking-tighter flex items-center justify-center gap-2">
          🐢 TAO-THAI
        </h1>
        <p className="text-sm font-medium opacity-80 uppercase tracking-widest">The Sassy Photo Booth</p>
      </div>

      <div className="flex-1 overflow-y-auto bg-gray-50 p-4">
        {state === AppState.IDLE && (
          <div className="h-full flex flex-col items-center justify-center text-center p-8 space-y-8">
            <div className="w-48 h-48 bg-green-100 rounded-full flex items-center justify-center border-4 border-dashed border-green-400 animate-bounce">
              <span className="text-8xl">🐢</span>
            </div>
            <div>
              <h2 className="text-3xl font-bold text-gray-800">ยินดีต้อนรับสู่เต่าถ่าย</h2>
              <p className="text-gray-500 mt-2">จะถ่ายจริงดิ? มั่นใจหน้าตาแล้วนะ?</p>
            </div>
            <button 
              onClick={handleStart}
              className="w-full py-6 bg-green-500 text-white text-2xl font-black rounded-2xl shadow-lg hover:bg-green-600 transform active:scale-95 transition-all"
            >
              กดเพื่อเริ่มถ่าย (ใจไม่ถึงอย่ากด)
            </button>
          </div>
        )}

        {state === AppState.MENU && (
          <div className="space-y-4">
            <h3 className="text-xl font-bold text-center text-gray-700 py-2 border-b">เลือกเมนู 'รสชาติของรูปถ่าย'</h3>
            <div className="grid grid-cols-1 gap-4">
              {MENU_ITEMS.map((item) => (
                <button
                  key={item.id}
                  onClick={() => selectMenu(item)}
                  className={`${item.color} p-4 rounded-3xl flex items-center gap-4 border-b-4 border-gray-300 active:border-b-0 active:translate-y-1 transition-all text-left shadow-sm`}
                >
                  <span className="text-4xl">{item.icon}</span>
                  <div>
                    <div className="font-bold text-lg">{item.name}</div>
                    <div className="text-sm opacity-70 leading-tight">{item.description}</div>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )}

        {(state === AppState.COUNTDOWN || state === AppState.PROCESSING) && (
          <div className="h-full flex flex-col items-center justify-center space-y-8">
            <div className="relative w-full aspect-square bg-black rounded-3xl overflow-hidden shadow-inner">
              <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                className={`w-full h-full object-cover ${state === AppState.PROCESSING ? 'opacity-30 blur-sm' : ''}`}
              />
              <canvas ref={canvasRef} className="hidden" />

              {state === AppState.COUNTDOWN && (
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="text-9xl font-black text-white drop-shadow-[0_10px_10px_rgba(0,0,0,0.5)] animate-ping">
                    {countdown}
                  </span>
                </div>
              )}
            </div>

            {state === AppState.PROCESSING && (
              <div className="text-center p-6 bg-white rounded-2xl shadow-md border-2 border-yellow-400 max-w-xs">
                <div className="animate-spin text-4xl mb-4">🌀</div>
                <p className="font-bold text-gray-800 text-lg">{insult}</p>
                <p className="text-xs text-gray-400 mt-2">กรุณารอสักครู่ เครื่องกำลังทำงานหนักมาก</p>
              </div>
            )}
          </div>
        )}

        {state === AppState.RESULT && result && (
          <div className="space-y-6 animate-in fade-in zoom-in duration-500">
            {/* The Vending Receipt Card */}
            <div className="bg-white p-4 rounded-xl border-2 border-dashed border-gray-300 shadow-lg font-mono relative overflow-hidden">
               <div className="text-center border-b pb-2 mb-4">
                  <h4 className="font-bold text-xl">TAO-THAI RECEIPT</h4>
                  <p className="text-[10px] text-gray-400">#001-PHOTO-SASSY-69</p>
               </div>

               <div className="flex flex-col items-center mb-4">
                  <div className="w-48 h-64 bg-gray-100 rounded-lg overflow-hidden border-2 border-gray-200 relative">
                    <img src={result.imageUrl} alt="Result" className="w-full h-full object-cover" />
                    <div className="absolute bottom-0 left-0 right-0 bg-black/50 text-white text-[10px] p-1 text-center italic">
                      รสชาติ: {result.menuName}
                    </div>
                  </div>
               </div>

               <div className="space-y-1 text-sm">
                  <div className="flex justify-between">
                    <span>ความหวาน:</span>
                    <span className="font-bold">{result.sweetness}% {result.sweetness > 80 ? '🍭' : '🌶️'}</span>
                  </div>
                  <div className="flex justify-between">
                    <span>แคลอรี่ (ความหนา):</span>
                    <span className="font-bold">{result.calories} kcal</span>
                  </div>
                  <div className="mt-4 pt-2 border-t text-xs">
                    <div className="font-bold mb-1 underline">คำทำนายจากดวงเต่า:</div>
                    <p className="italic text-gray-600">{result.fortune}</p>
                  </div>
               </div>

               <div className="mt-6 flex flex-col items-center">
                  <div className="bg-white p-2 border border-black mb-1">
                    <img src="https://api.qrserver.com/v1/create-qr-code/?size=100x100&data=TAOTHAI_SECRET_BAD_PHOTO" className="w-20 h-20" />
                  </div>
                  <p className="text-[8px]">สแกนเพื่อรับหลักฐานความสวย</p>
               </div>
            </div>

            {/* Action Buttons */}
            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => share('fb')} className="bg-blue-600 text-white p-3 rounded-xl text-xs font-bold shadow-md active:scale-95 transition-all">Facebook</button>
              <button onClick={() => share('ig')} className="bg-gradient-to-tr from-yellow-400 via-red-500 to-purple-600 text-white p-3 rounded-xl text-xs font-bold shadow-md active:scale-95 transition-all">Instagram</button>
              <button onClick={() => share('tt')} className="bg-black text-white p-3 rounded-xl text-xs font-bold shadow-md active:scale-95 transition-all">TikTok</button>
              <button 
                onClick={() => alert("เสียใจด้วย ลบไม่ได้ รูปคุณมันเด็ดเกินไป!")} 
                className="bg-red-100 text-red-600 p-3 rounded-xl text-xs font-bold border-2 border-red-200 shadow-md active:scale-95 transition-all"
              >
                🗑️ ปุ่มถังขยะ
              </button>
            </div>

            <button 
              onClick={reset}
              className="w-full py-4 bg-green-500 text-white rounded-2xl font-bold shadow-xl hover:bg-green-600 active:scale-95 transition-all"
            >
              เอาอีกลูกค้า (ถ่ายใหม่)
            </button>
          </div>
        )}
      </div>

      {/* Footer Branding */}
      <div className="p-4 bg-gray-100 text-center text-gray-400 text-[10px] uppercase font-bold tracking-widest border-t">
        PROUDLY MADE IN THE TURTLE SHELL &copy; 2024
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef } from 'react';
import { AppStep, Persona, MemeVariant, MemeEntry, CharacterStats } from './types';
import CameraCapture from './components/CameraCapture';
import { processImageWithGemini } from './services/geminiService';
import { playSarcasticVoice } from './services/audioService';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [selectedVariant, setSelectedVariant] = useState<MemeVariant | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [leaderboard, setLeaderboard] = useState<MemeEntry[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const compositionCanvasRef = useRef<HTMLCanvasElement>(null);

  const attractLines = [
    "เดินผ่านมาเฉยๆ ทำไม มาลองเป็นคนจิ๋วดูหน่อยมั้ย",
    "ตู้ย่อส่วนว่างอยู่นะจ๊ะ สนใจมาทำคำคมประชดชีวิตมั้ย",
    "หน้าตาดีแบบนี้ เหมาะจะเป็น Specimen ในคอลเลกชันของผมจริงๆ",
    "เบื่อโลกใบใหญ่หรือยัง มาลองใช้ชีวิตแบบมดดูบ้างสิ",
    "รับคำคมคนจิ๋วฟรีครับ ไม่เสียเงินแต่เสียสติแน่นอน",
    "มองอะไรน่ะ? สนใจก็เดินเข้ามาสิ เดี๋ยวจัดคำคมเด็ดๆ ให้",
    "เฮ้! คุณน่ะ มาลองปั่น DNA ตัวเองให้กลายเป็นคนจิ๋วดูหน่อยมั้ย?"
  ];

  const captureLines = [
    "โอ้โห หน้าตาใช้ได้เลยนะเนี่ย ต่อไปเลือกส่วนผสมที่ชอบเลย",
    "รับทราบครับ บันทึกใบหน้าเรียบร้อย ต่อไปเลือกสารสกัดที่จะผสมด้วยสิ",
    "ว้าว Specimen รายนี้ดูน่าสนใจมาก เลือกไอเทมที่จะผสมเลยครับ",
    "ถ่ายรูปเสร็จแล้ว หล่อเท่เอาเรื่อง! ไปดูส่วนผสมกันต่อเลย"
  ];

  const processLines = (additive: string) => [
    `กำลังปั่น ${additive} เข้ากับ DNA ของคุณ... อย่าเพิ่งกลายร่างนะ`,
    `แหม เลือก ${additive} ซะด้วย รสชาตินี้มันกาวจริงๆ รอแป๊บนะ`,
    `เริ่มกระบวนการควบแน่น ${additive} แล้วครับ รอดูความมหัศจรรย์ได้เลย`,
    `เครื่องกำลังวิเคราะห์ ${additive} เพื่อสร้างคำคมที่เจ็บที่สุดให้คุณ!`
  ];

  const resultLines = [
    "เสร็จแล้ว! ดูคำคมประจำตัวสิ เจ็บจี๊ดจนมดยังร้องไห้",
    "นี่คือร่างใหม่ของคุณครับ เล็กพริกขี้หนู แต่หนูอาจจะกินคุณได้นะ",
    "แปลงร่างสำเร็จ! คำคมนี้ผมคัดมาเพื่อคุณโดยเฉพาะเลย",
    "ได้รูปแล้ว! ลองอ่านคำคมสิ รับรองว่าจุกจนพูดไม่ออก"
  ];

  useEffect(() => {
    let interval: number;
    if (step === AppStep.WELCOME) {
      const speakRandom = () => {
        const line = attractLines[Math.floor(Math.random() * attractLines.length)];
        playSarcasticVoice(line);
      };
      speakRandom();
      interval = window.setInterval(speakRandom, 18000); 
    }
    return () => clearInterval(interval);
  }, [step]);

  const handleImageInput = (image: string) => {
    setCapturedImage(image);
    setStep(AppStep.MIXING);
    const line = captureLines[Math.floor(Math.random() * captureLines.length)];
    playSarcasticVoice(line);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => { if (ev.target?.result) handleImageInput(ev.target.result as string); };
      reader.readAsDataURL(file);
    }
  };

  const startTransformation = async (additive: string) => {
    if (!capturedImage) return;
    setStep(AppStep.PROCESSING);
    const lines = processLines(additive);
    playSarcasticVoice(lines[Math.floor(Math.random() * lines.length)]);
    setIsProcessing(true);
    try {
      const data = await processImageWithGemini(capturedImage, additive, 'th');
      setSelectedVariant(data[0]);
      setStep(AppStep.RESULT);
      const resLine = resultLines[Math.floor(Math.random() * resultLines.length)];
      playSarcasticVoice(resLine);
    } catch (error) {
      console.error(error);
      setStep(AppStep.WELCOME);
    } finally {
      setIsProcessing(false);
    }
  };

  const renderObservationView = (variant: MemeVariant, isSmall = false) => {
    const stats = variant.stats;
    return (
      <div id="capture-area" className={`relative bg-white p-3 rounded-[2.5rem] overflow-hidden shadow-2xl transition-all border-4 border-white ${isSmall ? 'scale-100' : 'hover:scale-[1.01]'}`}>
        <div className="relative rounded-[1.8rem] overflow-hidden bg-neutral-900 aspect-[3/4]">
          <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start z-10">
            <div className="bg-black/70 backdrop-blur-md px-3 py-1.5 rounded-lg border-l-4 border-cyan-400">
              <span className="text-[10px] font-black text-cyan-400 block uppercase tracking-tighter">Specimen: {stats?.rarity}</span>
              <span className="text-white text-xs font-bold">{variant.quote}</span>
            </div>
          </div>
          <img src={variant.imageUrl} className="w-full h-full object-cover" alt="Observation" />
        </div>
        <div className="bg-white p-6 text-center">
           <i className="fas fa-quote-left text-cyan-100 text-4xl mb-2 block"></i>
           <p className="text-neutral-800 font-black text-xl italic leading-tight px-2">"{variant.styleLabel}"</p>

           <div className="mt-5 flex flex-wrap justify-center gap-2">
             <span className="px-3 py-1.5 bg-blue-50 text-blue-600 text-[11px] font-bold rounded-full border border-blue-100">#DonboscoSurat</span>
             <span className="px-3 py-1.5 bg-orange-50 text-orange-600 text-[11px] font-bold rounded-full border border-orange-100">#เรียนสายอาชีพ</span>
           </div>

           <div className="mt-6 pt-5 border-t border-dashed border-neutral-200 flex justify-between items-center text-[10px] font-black uppercase text-neutral-400 tracking-widest">
             <span>ELEMENT: {stats?.element}</span>
             <span className="text-cyan-500">TAO-TINY STATION</span>
           </div>
        </div>
      </div>
    );
  };

  const handleDownload = async () => {
    if (!selectedVariant || !compositionCanvasRef.current) return;
    const canvas = compositionCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      // High resolution for 3:4 aspect ratio card
      canvas.width = 1000;
      canvas.height = 1350;

      // 1. Draw Transparent/White Rounded Base
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.roundRect(0, 0, canvas.width, canvas.height, 80);
      ctx.fill();

      // 2. Draw Main Image with Rounded Corners (Top Area)
      const padding = 12;
      const imgWidth = canvas.width - (padding * 2);
      const imgHeight = imgWidth * (4/3);

      ctx.save();
      ctx.beginPath();
      ctx.roundRect(padding, padding, imgWidth, imgHeight, 60);
      ctx.clip();
      ctx.drawImage(img, padding, padding, imgWidth, imgHeight);
      ctx.restore();

      // 3. Draw Specimen Tag
      ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
      ctx.beginPath();
      ctx.roundRect(padding + 30, padding + 30, 450, 90, 20);
      ctx.fill();
      ctx.fillStyle = '#22d3ee'; // cyan-400
      ctx.fillRect(padding + 30, padding + 30, 8, 90);

      ctx.font = 'black 18px Kanit';
      ctx.fillStyle = '#22d3ee';
      ctx.fillText(`SPECIMEN: ${selectedVariant.stats?.rarity}`, padding + 55, padding + 65);
      ctx.font = 'bold 24px Kanit';
      ctx.fillStyle = '#ffffff';
      ctx.fillText(selectedVariant.quote.toUpperCase(), padding + 55, padding + 100);

      // 4. Draw Bottom Content Area
      const contentY = padding + imgHeight + 40;

      // Quote Icon
      ctx.font = '900 80px Kanit';
      ctx.fillStyle = '#ecfeff'; // cyan-50
      ctx.textAlign = 'center';
      ctx.fillText('“', canvas.width / 2, contentY + 20);

      // Quote Text (Wrapped)
      ctx.fillStyle = '#171717'; // neutral-900
      ctx.font = 'italic 900 42px Kanit';
      const text = `"${selectedVariant.styleLabel}"`;
      const words = text.split(' ');
      let line = '';
      let y = contentY + 60;
      const maxWidth = canvas.width - 120;
      for(let n = 0; n < words.length; n++) {
        let testLine = line + words[n] + ' ';
        if (ctx.measureText(testLine).width > maxWidth && n > 0) {
          ctx.fillText(line, canvas.width/2, y);
          line = words[n] + ' ';
          y += 55;
        } else {
          line = testLine;
        }
      }
      ctx.fillText(line, canvas.width/2, y);

      // 5. HashTags
      const tagY = y + 60;
      ctx.font = 'bold 22px Kanit';
      const tag1 = '#DonboscoSurat';
      const tag1W = ctx.measureText(tag1).width + 40;
      ctx.fillStyle = '#eff6ff'; // blue-50
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) - tag1W - 10, tagY, tag1W, 50, 25);
      ctx.fill();
      ctx.fillStyle = '#2563eb';
