      ctx.setLineDash([10, 10]);
      ctx.strokeStyle = '#e5e5e5';
      ctx.beginPath();
      ctx.moveTo(80, footerY - 30);
      ctx.lineTo(canvas.width - 80, footerY - 30);
      ctx.stroke();

