        </div>
        <div className="bg-white p-6 text-center">
           <i className="fas fa-quote-left text-cyan-100 text-4xl mb-2 block"></i>
           <p className="text-neutral-800 font-black text-xl italic leading-tight px-2">"{variant.styleLabel}"</p>

           <div className="mt-5 flex flex-wrap justify-center gap-2">
             <span className="px-3 py-1.5 bg-blue-50 text-blue-600 text-[11px] font-bold rounded-full border border-blue-100">#DonboscoSurat</span>
             <span className="px-3 py-1.5 bg-orange-50 text-orange-600 text-[11px] font-bold rounded-full border border-orange-100">#เรียนสายอาชีพ</span>
           </div>

           <div className="mt-6 pt-5 border-t border-dashed border-neutral-200 flex justify-between items-center text-[10px] font-black uppercase text-neutral-400 tracking-widest">
             <span>ELEMENT: {stats?.element}</span>
             <span className="text-cyan-500">TAO-TINY STATION</span>
           </div>
        </div>
      </div>
    );
