  const handleDownload = async () => {
    if (!selectedVariant || !compositionCanvasRef.current) return;
    const canvas = compositionCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      canvas.width = 1000;
      canvas.height = 1350;

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.roundRect(0, 0, canvas.width, canvas.height, 80);
      ctx.fill();

      const padding = 15;
      const imgWidth = canvas.width - (padding * 2);
      const imgHeight = imgWidth * (4/3);

      ctx.save();
      ctx.beginPath();
      ctx.roundRect(padding, padding, imgWidth, imgHeight, 60);
      ctx.clip();
      ctx.drawImage(img, padding, padding, imgWidth, imgHeight);
      ctx.restore();

      ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
      ctx.beginPath();
      ctx.roundRect(padding + 30, padding + 30, 480, 95, 20);
      ctx.fill();
      ctx.fillStyle = '#22d3ee';
      ctx.fillRect(padding + 30, padding + 30, 10, 95);

      ctx.font = '900 20px Kanit';
      ctx.fillStyle = '#22d3ee';
      ctx.fillText(`SPECIMEN: ${selectedVariant.stats?.rarity}`, padding + 55, padding + 68);
      ctx.font = 'bold 26px Kanit';
      ctx.fillStyle = '#ffffff';
      ctx.fillText(selectedVariant.quote.toUpperCase(), padding + 55, padding + 105);

      const contentY = padding + imgHeight + 60;
      ctx.font = '900 120px Kanit';
      ctx.fillStyle = '#ecfeff';
      ctx.textAlign = 'center';
      ctx.fillText('“', canvas.width / 2, contentY + 30);

      ctx.fillStyle = '#171717';
      ctx.font = 'italic 900 48px Kanit';
      ctx.textAlign = 'center';

      const text = `"${selectedVariant.styleLabel}"`;
      const maxWidth = canvas.width - 150;
      const words = text.split(' ');
      let line = '';
      let y = contentY + 80;

      for(let n = 0; n < words.length; n++) {
        let testLine = line + words[n] + ' ';
        if (ctx.measureText(testLine).width > maxWidth && n > 0) {
          ctx.fillText(line.trim(), canvas.width/2, y);
          line = words[n] + ' ';
          y += 65;
        } else {
          line = testLine;
        }
      }
      ctx.fillText(line.trim(), canvas.width/2, y);

      const tagY = y + 80;
      ctx.font = 'bold 24px Kanit';
      const tag1 = '#DonboscoSurat';
      const tag1W = ctx.measureText(tag1).width + 50;
      ctx.fillStyle = '#eff6ff';
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) - tag1W - 15, tagY, tag1W, 60, 30);
      ctx.fill();
      ctx.fillStyle = '#2563eb';
      ctx.fillText(tag1, (canvas.width/2) - (tag1W/2) - 15, tagY + 40);

      const tag2 = '#เรียนสายอาชีพ';
      const tag2W = ctx.measureText(tag2).width + 50;
      ctx.fillStyle = '#fff7ed';
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) + 15, tagY, tag2W, 60, 30);
      ctx.fill();
      ctx.fillStyle = '#ea580c';
      ctx.fillText(tag2, (canvas.width/2) + (tag2W/2) + 15, tagY + 40);

      const footerY = canvas.height - 70;
      ctx.setLineDash([10, 10]);
      ctx.strokeStyle = '#e5e5e5';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(80, footerY - 40);
      ctx.lineTo(canvas.width - 80, footerY - 40);
      ctx.stroke();

      ctx.font = '900 20px Kanit';
      ctx.fillStyle = '#a3a3a3';
      ctx.textAlign = 'left';
      ctx.fillText(`ELEMENT: ${selectedVariant.stats?.element.toUpperCase()}`, 80, footerY);
      ctx.textAlign = 'right';
      ctx.fillStyle = '#06b6d4';
      ctx.fillText('TAO-TINY STATION', canvas.width - 80, footerY);

      const link = document.createElement('a');
      link.href = canvas.toDataURL('image/png', 1.0);
      link.download = `TAO_TINY_${Date.now()}.png`;
      link.click();
    };
    img.src = selectedVariant.imageUrl;
  };

  const shareSocial = async () => {
    if (!selectedVariant) return;
    const text = `ดูคำคมคนจิ๋วของผมสิ! "${selectedVariant.styleLabel}" #DonboscoSurat #เรียนสายอาชีพ`;

    // Check if the browser supports the Web Share API
    if (navigator.share) {
      try {
        await navigator.share({
          title: 'TAO-TINY Specimen',
          text: text,
          url: window.location.href,
        });
      } catch (err) {
