      ctx.beginPath();
      ctx.roundRect((canvas.width/2) - tag1W - 20, tagY, tag1W, 70, 35);
      ctx.fill();
      ctx.fillStyle = '#2563eb';
      ctx.fillText(tag1, (canvas.width/2) - (tag1W/2) - 20, tagY + 45);

      const tag2 = '#เรียนสายอาชีพ';
      const tag2W = ctx.measureText(tag2).width + 60;
      ctx.fillStyle = '#fff7ed'; // orange-50
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) + 20, tagY, tag2W, 70, 35);
