      const footerY = canvas.height - 80;
      ctx.setLineDash([15, 15]);
      ctx.strokeStyle = '#e5e5e5';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(100, footerY - 50);
