import React, { useState, useEffect, useRef } from 'react';
import { AppStep, Persona, MemeVariant, MemeEntry, CharacterStats } from './types';
import CameraCapture from './components/CameraCapture';
import { processImageWithGemini } from './services/geminiService';
import { playSarcasticVoice } from './services/audioService';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.WELCOME);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [selectedVariant, setSelectedVariant] = useState<MemeVariant | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [leaderboard, setLeaderboard] = useState<MemeEntry[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const compositionCanvasRef = useRef<HTMLCanvasElement>(null);

  const attractLines = [
    "เดินผ่านมาเฉยๆ ทำไม มาลองเป็นคนจิ๋วดูหน่อยมั้ย",
    "ตู้ย่อส่วนว่างอยู่นะจ๊ะ สนใจมาทำคำคมประชดชีวิตมั้ย",
    "หน้าตาดีแบบนี้ เหมาะจะเป็น Specimen ในคอลเลกชันของผมจริงๆ",
    "เบื่อโลกใบใหญ่หรือยัง มาลองใช้ชีวิตแบบมดดูบ้างสิ",
    "รับคำคมคนจิ๋วฟรีครับ ไม่เสียเงินแต่เสียสติแน่นอน"
  ];

  const captureLines = [
    "โอ้โห หน้าตาใช้ได้เลยนะเนี่ย ต่อไปเลือกส่วนผสมที่ชอบเลย",
    "ถ่ายรูปเสร็จแล้ว หล่อเท่เอาเรื่อง! ไปดูส่วนผสมกันต่อเลย"
  ];

  useEffect(() => {
    let interval: number;
    if (step === AppStep.WELCOME) {
      const speakRandom = () => {
        const line = attractLines[Math.floor(Math.random() * attractLines.length)];
        playSarcasticVoice(line);
      };
      speakRandom();
      interval = window.setInterval(speakRandom, 18000); 
    }
    return () => clearInterval(interval);
  }, [step]);

  const handleImageInput = (image: string) => {
    setCapturedImage(image);
    setStep(AppStep.MIXING);
    const line = captureLines[Math.floor(Math.random() * captureLines.length)];
    playSarcasticVoice(line);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => { if (ev.target?.result) handleImageInput(ev.target.result as string); };
      reader.readAsDataURL(file);
    }
  };

  const startTransformation = async (additive: string) => {
    if (!capturedImage) return;
    setStep(AppStep.PROCESSING);
    setIsProcessing(true);
    try {
      const data = await processImageWithGemini(capturedImage, additive, 'th');
      setSelectedVariant(data[0]);
      setStep(AppStep.RESULT);
      playSarcasticVoice("แปลงร่างสำเร็จ! คำคมนี้ผมคัดมาเพื่อคุณโดยเฉพาะเลย");
    } catch (error) {
      console.error(error);
      setStep(AppStep.WELCOME);
    } finally {
      setIsProcessing(false);
    }
  };

  const renderObservationView = (variant: MemeVariant) => {
    const stats = variant.stats;
    return (
      <div id="capture-area" className="relative bg-white p-3 rounded-[3.5rem] overflow-hidden shadow-2xl border-4 border-white transition-all transform hover:scale-[1.01]">
        {/* Main Image with inner rounded corners */}
        <div className="relative rounded-[2.8rem] overflow-hidden bg-neutral-900 aspect-[3/4] shadow-inner">
          <img src={variant.imageUrl} className="w-full h-full object-cover" alt="Observation" />

          {/* Top Label Tag */}
          <div className="absolute top-6 left-6 z-10 max-w-[80%]">
            <div className="bg-black/70 backdrop-blur-lg px-4 py-2 rounded-2xl border-l-[10px] border-cyan-400">
              <span className="text-[10px] font-black text-cyan-400 block uppercase tracking-tighter">SPECIMEN: {stats?.rarity}</span>
              <span className="text-white text-sm font-bold truncate block">{variant.quote}</span>
            </div>
          </div>
        </div>

        {/* Card Footer Content */}
        <div className="bg-white p-8 pt-6 text-center">
           <div className="flex justify-center mb-2">
             <i className="fas fa-quote-left text-cyan-100 text-6xl opacity-70"></i>
           </div>

           <h2 className="text-neutral-900 font-black text-2xl italic leading-tight px-4 mb-6">
             "{variant.styleLabel}"
           </h2>

           <div className="flex flex-wrap justify-center gap-3 mb-8">
             <span className="px-5 py-2 bg-blue-50 text-blue-600 text-[12px] font-black rounded-full border border-blue-100">#DonboscoSurat</span>
             <span className="px-5 py-2 bg-orange-50 text-orange-600 text-[12px] font-black rounded-full border border-orange-100">#เรียนสายอาชีพ</span>
           </div>

           <div className="pt-6 border-t border-dashed border-neutral-200 flex justify-between items-center text-[10px] font-black uppercase text-neutral-400 tracking-widest">
             <span className="flex-1 text-left">ELEMENT: {stats?.element}</span>
             <span className="flex-1 text-right text-cyan-500">TAO-TINY STATION</span>
           </div>
        </div>
      </div>
    );
  };

  const handleDownload = async () => {
    if (!selectedVariant || !compositionCanvasRef.current) return;
    const canvas = compositionCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      // 1000x1400 high-res card
      canvas.width = 1000;
      canvas.height = 1400;

      // Clear and draw white background card
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.roundRect(0, 0, canvas.width, canvas.height, 100);
      ctx.fill();

      // Main Image Padding & Size
      const pad = 25;
      const imgW = canvas.width - (pad * 2);
      const imgH = imgW * (4/3);

      // Draw Main Image Rounded
      ctx.save();
      ctx.beginPath();
      ctx.roundRect(pad, pad, imgW, imgH, 80);
      ctx.clip();
      ctx.drawImage(img, pad, pad, imgW, imgH);
      ctx.restore();

      // Draw Specimen Tag
      const tagX = pad + 40;
      const tagY = pad + 40;
      ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
      ctx.beginPath();
      ctx.roundRect(tagX, tagY, 520, 110, 25);
      ctx.fill();
      ctx.fillStyle = '#22d3ee'; // cyan-400
      ctx.fillRect(tagX, tagY, 12, 110);

      ctx.font = '900 24px Kanit';
      ctx.fillStyle = '#22d3ee';
      ctx.textAlign = 'left';
      ctx.fillText(`SPECIMEN: ${selectedVariant.stats?.rarity}`, tagX + 40, tagY + 45);
      ctx.font = 'bold 30px Kanit';
      ctx.fillStyle = '#ffffff';
      ctx.fillText(selectedVariant.quote.toUpperCase(), tagX + 40, tagY + 90);

      // Bottom Area Content
      const startY = pad + imgH + 80;

      // Quote Mark
      ctx.font = '900 160px Kanit';
      ctx.fillStyle = '#ecfeff';
      ctx.textAlign = 'center';
      ctx.fillText('“', canvas.width / 2, startY + 50);

      // Wrapped Quote Text
      ctx.fillStyle = '#171717';
      ctx.font = 'italic 900 52px Kanit';
      ctx.textAlign = 'center';
      const quoteText = `"${selectedVariant.styleLabel}"`;
      const maxWidth = canvas.width - 200;
      const words = quoteText.split(' ');
      let line = '';
      let textY = startY + 110;

      for(let n = 0; n < words.length; n++) {
        let testLine = line + words[n] + ' ';
        if (ctx.measureText(testLine).width > maxWidth && n > 0) {
          ctx.fillText(line.trim(), canvas.width/2, textY);
          line = words[n] + ' ';
          textY += 75;
        } else {
          line = testLine;
        }
      }
      ctx.fillText(line.trim(), canvas.width/2, textY);

      // Hashtags
      const tagBaseY = textY + 80;
      ctx.font = 'bold 28px Kanit';
      const h1 = '#DonboscoSurat';
      const h1W = ctx.measureText(h1).width + 60;
      ctx.fillStyle = '#eff6ff';
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) - h1W - 15, tagBaseY, h1W, 70, 35);
      ctx.fill();
      ctx.fillStyle = '#2563eb';
      ctx.fillText(h1, (canvas.width/2) - (h1W/2) - 15, tagBaseY + 45);

      const h2 = '#เรียนสายอาชีพ';
      const h2W = ctx.measureText(h2).width + 60;
      ctx.fillStyle = '#fff7ed';
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) + 15, tagBaseY, h2W, 70, 35);
      ctx.fill();
      ctx.fillStyle = '#ea580c';
      ctx.fillText(h2, (canvas.width/2) + (h2W/2) + 15, tagBaseY + 45);

      // Dash Footer
      const footY = canvas.height - 80;
      ctx.setLineDash([15, 15]);
      ctx.strokeStyle = '#e5e5e5';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(100, footY - 50);
      ctx.lineTo(canvas.width - 100, footY - 50);
      ctx.stroke();

      ctx.font = '900 24px Kanit';
      ctx.fillStyle = '#a3a3a3';
      ctx.textAlign = 'left';
      ctx.fillText(`ELEMENT: ${selectedVariant.stats?.element.toUpperCase()}`, 100, footY);
      ctx.textAlign = 'right';
      ctx.fillStyle = '#06b6d4';
      ctx.fillText('TAO-TINY STATION', canvas.width - 100, footY);

      const link = document.createElement('a');
      link.href = canvas.toDataURL('image/png', 1.0);
      link.download = `TAO_TINY_${Date.now()}.png`;
      link.click();
    };
    img.src = selectedVariant.imageUrl;
  };

  const shareSocial = async () => {
    if (!selectedVariant) return;
    const text = `ดูคำคมคนจิ๋วของผมสิ! "${selectedVariant.styleLabel}" #DonboscoSurat #เรียนสายอาชีพ`;
    if (navigator.share) {
      try {
        await navigator.share({
          title: 'TAO-TINY Specimen',
          text: text,
          url: window.location.href,
        });
      } catch (err) {}
    } else {
      window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`, '_blank');
    }
  };

  const additives = [
    { name: 'มาม่าเผ็ด', desc: 'เพิ่มพลังงานช่วงใกล้สอบ', icon: 'fa-fire', id: 'noodle' },
    { name: 'น้ำแดงมะนาว', desc: 'หวานเจี๊ยบชื่นใจ', icon: 'fa-glass-water', id: 'syrup' },
    { name: 'กาแฟค้างคืน', desc: 'ตื่นตัว 5 นาที หลับ 5 ชั่วโมง', icon: 'fa-mug-hot', id: 'coffee' },
    { name: 'ผงพิเศษ', desc: 'สิวหายแต่สมองเบลอ', icon: 'fa-wand-magic-sparkles', id: 'magic' },
    { name: 'สูตรลับช่างกล', desc: 'อุปกรณ์หายหมด', icon: 'fa-wrench', id: 'mechanic' },
    { name: 'ชานมไข่มุก', desc: 'สุขดีแบบมโน', icon: 'fa-cup-togo', id: 'boba' },
    { name: 'สารสกัดตำรา', desc: 'เข้มข้นจนวิงเวียน', icon: 'fa-book-open', id: 'study' },
    { name: 'อิเล็กทรอนิกส์', desc: 'วงจรชีวิตพัง', icon: 'fa-microchip', id: 'elec' }
  ];

  return (
    <div className="max-w-6xl mx-auto min-h-screen flex flex-col p-4 md:p-8 relative z-20">
      <header className="flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
        <div className="text-center md:text-left">
           <h1 className="text-5xl md:text-7xl font-black text-white italic uppercase tracking-tighter transform -skew-x-6">
             TAO <span className="text-cyan-400">TINY</span>
           </h1>
           <p className="text-cyan-400/60 font-mono text-[10px] uppercase tracking-[0.4em] mt-1">Automatic Micro-Vending Station</p>
        </div>
        <button onClick={() => setStep(AppStep.WELCOME)} className="px-6 py-2 bg-white/5 border border-white/10 text-[10px] font-black uppercase text-white hover:bg-white/10">Home</button>
      </header>

      <main className="flex-1 w-full flex flex-col items-center">
        {step === AppStep.WELCOME && (
          <div className="w-full max-w-4xl text-center animate-in fade-in zoom-in">
             <div className="bg-white/5 border border-white/10 p-12 rounded-[3rem] backdrop-blur-xl">
                <h2 className="text-6xl font-black text-white mb-10 uppercase italic">รับคำคมคนจิ๋วฟรี</h2>
                <div className="flex flex-col sm:flex-row justify-center gap-6">
                  <button onClick={() => setStep(AppStep.CAPTURE)} className="px-10 py-6 bg-cyan-500 text-black text-2xl font-black rounded-3xl hover:bg-white flex-1 transition-all shadow-[0_0_30px_rgba(34,211,238,0.3)]">ถ่ายใหม่</button>
                  <button onClick={() => fileInputRef.current?.click()} className="px-10 py-6 border-4 border-white text-white text-2xl font-black rounded-3xl hover:bg-white hover:text-black flex-1 transition-all">เลือกรูป
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload}/></button>
                </div>
             </div>
          </div>
        )}

        {step === AppStep.CAPTURE && <CameraCapture onCapture={handleImageInput} onCancel={() => setStep(AppStep.WELCOME)} />}

        {step === AppStep.MIXING && (
          <div className="w-full max-w-5xl animate-in slide-in-from-bottom">
            <h2 className="text-4xl font-black text-white mb-8 text-center uppercase italic">เลือกส่วนผสมที่จะปั่น</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {additives.map(item => (
                <button key={item.id} onClick={() => startTransformation(item.name)} className="flex flex-col p-6 bg-white/5 border border-white/10 rounded-3xl hover:bg-cyan-500 hover:text-black transition-all group shadow-lg">
                   <i className={`fas ${item.icon} text-2xl mb-4 text-cyan-400 group-hover:text-black`}></i>
                   <span className="font-black text-lg uppercase text-white group-hover:text-black">{item.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {step === AppStep.PROCESSING && (
          <div className="flex flex-col items-center py-20 text-center">
            <div className="relative w-32 h-32 mb-8">
              <div className="absolute inset-0 border-4 border-cyan-400 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <h3 className="text-4xl font-black text-white italic uppercase">กำลังย่อส่วนคุณ...</h3>
          </div>
        )}

        {step === AppStep.RESULT && selectedVariant && (
          <div className="w-full max-w-lg animate-in slide-in-from-bottom duration-700 pb-20">
            {renderObservationView(selectedVariant)}

            <div className="mt-8 space-y-4">
              <button onClick={handleDownload} className="w-full py-6 bg-cyan-500 text-black font-black text-2xl uppercase italic rounded-full shadow-[0_10px_30px_rgba(34,211,238,0.4)] hover:bg-white transition-all">
