              </button>

              <button onClick={shareSocial} className="w-full py-5 bg-white text-black font-black text-xl uppercase italic rounded-full flex items-center justify-center gap-3">
                <i className="fas fa-share-nodes"></i> แชร์ไปยังแอปอื่น
              </button>

              <button onClick={() => setStep(AppStep.WELCOME)} className="w-full py-4 bg-transparent border-2 border-white/20 text-white font-black uppercase text-xs rounded-full">ทำใหม่</button>
            </div>
