let audioContext: AudioContext | null = null;
let currentSource: AudioBufferSourceNode | null = null;
let lastCallTime = 0;
const MIN_INTERVAL = 2000; // 2 seconds minimum between TTS calls

export const playSarcasticVoice = async (text: string) => {
  const now = Date.now();
  if (now - lastCallTime < MIN_INTERVAL) return;
  lastCallTime = now;

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `พูดด้วยน้ำเสียงกวนประสาทและขี้เล่น: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      if (!audioContext) {
        audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      if (audioContext.state === 'suspended') {
        await audioContext.resume();
      }

      if (currentSource) {
        try {
          currentSource.stop();
          currentSource.disconnect();
        } catch (e) {}
      }

      const binaryString = atob(base64Audio);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const dataInt16 = new Int16Array(bytes.buffer);
      const frameCount = dataInt16.length;
      const buffer = audioContext.createBuffer(1, frameCount, 24000);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const source = audioContext.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContext.destination);
      currentSource = source;
      source.start();
    }
  } catch (error: any) {
    if (error?.message?.includes('429')) {
      console.warn("TTS Rate limit reached. Skipping voice.");
    } else {
      console.error("Audio playback failed", error);
    }
  }
};

