      canvas.width = 1200;
      canvas.height = 1800; // Fixed high portrait ratio

      // 1. White Card Base
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.roundRect(0, 0, canvas.width, canvas.height, 120);
      ctx.fill();

      // 2. Photo Area (Rounded)
      const pad = 40;
      const imgW = canvas.width - (pad * 2);
      const imgH = imgW * (4/3);

      ctx.save();
      ctx.beginPath();
      ctx.roundRect(pad, pad, imgW, imgH, 100);
      ctx.clip();
      ctx.drawImage(img, pad, pad, imgW, imgH);
      ctx.restore();

      // 3. Specimen Tag (Overlay)
      const tagX = pad + 60;
      const tagY = pad + 60;
      ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
      ctx.beginPath();
      ctx.roundRect(tagX, tagY, 700, 150, 35);
      ctx.fill();
      ctx.fillStyle = '#22d3ee';
      ctx.fillRect(tagX, tagY, 15, 150);

      ctx.font = '900 32px Kanit';
