      ctx.fillStyle = '#ffffff';
      ctx.fillText(selectedVariant.quote.toUpperCase(), tagX + 50, tagY + 115);

      // 4. White Area - Quote and Tags
      const footerAreaY = pad + imgH + 110;

      // Giant Quote Icon
      ctx.font = '900 240px Kanit';
      ctx.fillStyle = '#ecfeff';
      ctx.textAlign = 'center';
      ctx.fillText('“', canvas.width / 2, footerAreaY + 110);

      // Wrapped Quote Text
      ctx.fillStyle = '#171717';
      ctx.font = 'italic 900 64px Kanit';
      ctx.textAlign = 'center';
      const quoteText = `"${selectedVariant.styleLabel}"`;
      const wrapWidth = canvas.width - 240;
      const words = quoteText.split(' ');
      let currentLine = '';
      let textY = footerAreaY + 180;

      for(let i = 0; i < words.length; i++) {
        let testLine = currentLine + words[i] + ' ';
        if (ctx.measureText(testLine).width > wrapWidth && i > 0) {
          ctx.fillText(currentLine.trim(), canvas.width/2, textY);
          currentLine = words[i] + ' ';
          textY += 90;
        } else {
          currentLine = testLine;
        }
      }
      ctx.fillText(currentLine.trim(), canvas.width/2, textY);

      // 5. Hashtags
      const hashtagsY = textY + 120;
      ctx.font = 'bold 36px Kanit';

      const tag1Text = '#DonboscoSurat';
      const tag1W = ctx.measureText(tag1Text).width + 80;
      ctx.fillStyle = '#eff6ff';
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) - tag1W - 25, hashtagsY, tag1W, 95, 47.5);
      ctx.fill();
      ctx.fillStyle = '#2563eb';
      ctx.fillText(tag1Text, (canvas.width/2) - (tag1W/2) - 25, hashtagsY + 62);

      const tag2Text = '#เรียนสายอาชีพ';
      const tag2W = ctx.measureText(tag2Text).width + 80;
      ctx.fillStyle = '#fff7ed';
      ctx.beginPath();
      ctx.roundRect((canvas.width/2) + 25, hashtagsY, tag2W, 95, 47.5);
      ctx.fill();
      ctx.fillStyle = '#ea580c';
      ctx.fillText(tag2Text, (canvas.width/2) + (tag2W/2) + 25, hashtagsY + 62);

      // 6. Footer Line & Stats
      const bottomY = canvas.height - 110;
      ctx.setLineDash([20, 20]);
      ctx.strokeStyle = '#e5e5e5';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(150, bottomY - 80);
      ctx.lineTo(canvas.width - 150, bottomY - 80);
      ctx.stroke();

      ctx.font = '900 30px Kanit';
      ctx.fillStyle = '#a3a3a3';
      ctx.textAlign = 'left';
      ctx.fillText(`ELEMENT: ${selectedVariant.stats?.element.toUpperCase()}`, 150, bottomY);
      ctx.textAlign = 'right';
      ctx.fillStyle = '#06b6d4';
      ctx.fillText('TAO-TINY STATION', canvas.width - 150, bottomY);

      const link = document.createElement('a');
      link.href = canvas.toDataURL('image/png', 1.0);
      link.download = `TAO_TINY_SPECIMEN_${Date.now()}.png`;
      link.click();
    };
    img.src = selectedVariant.imageUrl;
