             TAO <span className="text-cyan-400">TINY</span>
           </h1>
           <p className="text-cyan-400/60 font-mono text-[10px] uppercase tracking-[0.4em] mt-1">Automatic Micro-Vending Station</p>
        </div>
        <button onClick={() => setStep(AppStep.WELCOME)} className="px-6 py-3 bg-white/5 border border-white/10 text-[12px] font-black uppercase text-white rounded-xl active:bg-white/20">Home</button>
      </header>

      <main className="flex-1 w-full flex flex-col items-center justify-center py-4">
        {step === AppStep.WELCOME && (
          <div className="w-full max-w-4xl text-center animate-in fade-in zoom-in duration-500 px-2">
             <div className="bg-white/5 border border-white/10 p-8 md:p-14 rounded-[2.5rem] md:rounded-[4rem] backdrop-blur-2xl shadow-2xl">
                <h2 className="text-4xl md:text-7xl font-black text-white mb-8 md:mb-12 uppercase italic leading-tight">รับคำคมคนจิ๋วฟรี</h2>
                <div className="flex flex-col sm:flex-row justify-center gap-4 md:gap-8">
                  <button onClick={() => { unlockAudio(); setStep(AppStep.CAPTURE); }} className="px-10 py-7 bg-cyan-500 text-black text-2xl md:text-3xl font-black rounded-[2rem] flex-1 shadow-[0_15px_40px_rgba(34,211,238,0.4)] hover:scale-105 active:scale-95 transition-all">ถ่ายใหม่</button>
                  <button onClick={() => { unlockAudio(); fileInputRef.current?.click(); }} className="px-10 py-7 border-4 border-white text-white text-2xl md:text-3xl font-black rounded-[2rem] flex-1 hover:bg-white hover:text-black transition-all">เลือกรูป
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload}/></button>
                </div>
             </div>
          </div>
        )}

        {step === AppStep.CAPTURE && <CameraCapture onCapture={handleImageInput} onCancel={() => setStep(AppStep.WELCOME)} />}

        {step === AppStep.MIXING && (
          <div className="w-full max-w-5xl animate-in slide-in-from-bottom duration-500">
            <h2 className="text-3xl md:text-4xl font-black text-white mb-8 text-center uppercase italic">เลือกส่วนผสมที่จะปั่น</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-5 px-2">
              {additives.map(item => (
                <button key={item.id} onClick={() => { unlockAudio(); startTransformation(item.name); }} className="flex flex-col items-center p-6 md:p-8 bg-white/5 border border-white/10 rounded-3xl hover:bg-cyan-500 hover:text-black active:bg-cyan-500 active:text-black group transition-all min-h-[140px] justify-center">
                   <i className={`fas ${item.icon} text-3xl mb-4 text-cyan-400 group-hover:text-black group-active:text-black`}></i>
                   <span className="font-black text-lg uppercase text-white group-hover:text-black group-active:text-black">{item.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {step === AppStep.PROCESSING && (
          <div className="flex flex-col items-center py-24 text-center">
            <div className="relative w-28 h-28 md:w-40 md:h-40 mb-10">
              <div className="absolute inset-0 border-[6px] border-cyan-400 border-t-transparent rounded-full animate-spin"></div>
              <div className="absolute inset-4 border-[3px] border-white/20 border-b-transparent rounded-full animate-spin-slow"></div>
            </div>
            <h3 className="text-4xl md:text-5xl font-black text-white italic uppercase tracking-wider">กำลังย่อส่วนคุณ...</h3>
            <p className="text-cyan-400/60 mt-4 font-mono text-sm uppercase">Optimizing cellular structure</p>
          </div>
        )}

        {step === AppStep.RESULT && selectedVariant && (
          <div className="w-full max-w-lg animate-in slide-in-from-bottom duration-500 pb-20 px-2">
            {renderObservationView(selectedVariant)}
            <div className="mt-8 space-y-4 px-4 md:px-0">
              <button onClick={handleDownload} className="w-full py-6 bg-cyan-500 text-black font-black text-2xl uppercase italic rounded-full shadow-[0_15px_40px_rgba(34,211,238,0.4)] active:scale-95 transition-all">
                บันทึกภาพใบคำคม (HD)
              </button>
              <button onClick={shareSocial} className="w-full py-5 bg-white text-black font-black text-xl uppercase italic rounded-full flex items-center justify-center gap-3 active:bg-cyan-100 transition-all">
                <i className="fas fa-share-nodes text-2xl"></i> ส่งต่อให้เพื่อน
              </button>
              <button onClick={() => setStep(AppStep.WELCOME)} className="w-full py-4 bg-transparent border-2 border-white/20 text-white font-black uppercase text-xs tracking-widest rounded-full active:bg-white/10 transition-all">สร้างใหม่อีกครั้ง</button>
            </div>
          </div>
        )}
        <canvas ref={compositionCanvasRef} className="hidden" />
      </main>
    </div>
  );
};

export default App;
